import React, { useState } from 'react';
import { useFeatureFlag } from '../context/FeatureFlagContext';
import { Menu, X } from 'react-feather';

const SidebarLayout = ({ children, activeTab, setActiveTab, handleLogout }) => {
    const { isEnabled } = useFeatureFlag();
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);

    // Core navigation items
    let navItems = [
        { id: 'dashboard', label: '📊 Dashboard' },
        { id: 'discover', label: '🔍 Discover' },
        { id: 'chat', label: '💬 Chats' },
        { id: 'matches', label: '❤️ Matches' },
        { id: 'requests', label: '   📬 Incoming Requests' },
        { id: 'sent-interests', label: '   🚀 Sent Interests' },
        { id: 'map', label: '📍 Nearby Map' },
        { id: 'passport', label: '🌍 Passport' }
    ];

    // Settings and Blocked Users always available as per design
    navItems.push({ id: 'blocked-users', label: '   🚫 Blocked Users' });
    navItems.push({ id: 'settings', label: '⚙️ Settings' });
    // navItems initialized above based on flags

    const toggleSidebar = () => setIsSidebarOpen(!isSidebarOpen);
    const closeSidebar = () => setIsSidebarOpen(false);

    return (
        <div style={{ display: 'flex', width: '100%', height: '100vh', backgroundColor: '#f3f4f6', position: 'relative', overflow: 'hidden' }}>
            {/* Mobile Overlay */}
            {isSidebarOpen && (
                <div 
                    onClick={closeSidebar}
                    style={{
                        position: 'fixed',
                        top: 0,
                        left: 0,
                        right: 0,
                        bottom: 0,
                        backgroundColor: 'rgba(0,0,0,0.5)',
                        zIndex: 40
                    }}
                    className="d-md-none"
                />
            )}

            {/* Sidebar */}
            <div 
                style={{ 
                    width: '250px', 
                    backgroundColor: '#ffffff', 
                    borderRight: '1px solid #e5e7eb', 
                    padding: '20px', 
                    display: 'flex', 
                    flexDirection: 'column',
                    position: 'absolute',
                    top: 0,
                    bottom: 0,
                    left: isSidebarOpen ? '0' : '-250px',
                    zIndex: 50,
                    transition: 'left 0.3s ease-in-out'
                }}
                className={`sidebar-menu ${isSidebarOpen ? 'open' : ''} d-md-flex position-md-static`}
            >
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px' }}>
                    <h2 style={{ fontSize: '1.5rem', fontWeight: 'bold', color: '#e11d48', margin: 0 }}>Penzi Admin</h2>
                    <button onClick={closeSidebar} className="d-md-none border-0 bg-transparent text-secondary p-0">
                        <X size={24} />
                    </button>
                </div>
                <nav style={{ flex: 1, overflowY: 'auto' }}>
                    {navItems.map(item => (
                        <button
                            key={item.id}
                            onClick={() => {
                                setActiveTab(item.id);
                                closeSidebar();
                            }}
                            style={{
                                display: 'block',
                                width: '100%',
                                textAlign: 'left',
                                padding: '12px 16px',
                                marginBottom: '8px',
                                borderRadius: '8px',
                                border: 'none',
                                cursor: 'pointer',
                                backgroundColor: activeTab === item.id ? '#ffe4e6' : 'transparent',
                                color: activeTab === item.id ? '#e11d48' : '#4b5563',
                                fontWeight: activeTab === item.id ? 'bold' : 'normal',
                                transition: 'background-color 0.2s'
                            }}
                        >
                            {item.label}
                        </button>
                    ))}
                </nav>
                <button 
                    onClick={handleLogout}
                    style={{ padding: '12px', border: 'none', backgroundColor: '#fef2f2', color: '#ef4444', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', transition: 'background-color 0.2s', marginTop: 'auto' }}
                >
                    Logout
                </button>
            </div>

            {/* Main Content Area */}
            <div style={{ flex: 1, overflowY: 'auto', display: 'flex', flexDirection: 'column' }}>
                {/* Mobile Header for Hamburger */}
                <div className="d-md-none d-flex align-items-center p-3 bg-white border-bottom shadow-sm flex-shrink-0">
                    <button onClick={toggleSidebar} className="border-0 bg-transparent p-0 me-3">
                        <Menu size={24} color="#4b5563" />
                    </button>
                    <h5 className="m-0 fw-bold" style={{ color: '#e11d48' }}>Penzi Dashboard</h5>
                </div>

                <div style={{ flex: 1 }}>
                    {children}
                </div>
            </div>

            <style>{`
                @media (min-width: 768px) {
                    .position-md-static {
                        position: static !important;
                    }
                    .d-md-none {
                        display: none !important;
                    }
                    .sidebar-menu:not(.d-md-flex) {
                        display: none;
                    }
                    .sidebar-menu.d-md-flex {
                        display: flex !important;
                    }
                }
            `}</style>
        </div>
    );
};

export default SidebarLayout;
